import tvl_bg from '@/assets/images/tvl_bg.png'
import yield_bg from '@/assets/images/yield_bg.png'
import HiddenDotted from '@/components/profile/HiddenDotted'
import useCalculatePendingYield from '@/hooks/position/useCalculatePendingYield'
import { useGetProfileLiquidityTvl } from '@/hooks/profile/useGetProfileLiquidityTvl'
import useDlmmPositionStore from '@/store/dlmm-position'
import usePositionStore from '@/store/position'
import { Block } from '@cetus/design'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import useTokenPriceStore from '@cetus/stores/src/tokenPrice'
import { Icon } from '@cetus/ui-kit'
import { formatCurrency } from '@cetus/utils'
import { Box, Button, HStack, Skeleton, Stack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import PendingYieldModal from './PendingYieldModal'
import PendingYieldValue from './PendingYieldValue'
function LiquidityAndYield({ isProfile = false }: { isProfile?: boolean }) {
  const { currentAccount } = useAccountStore()
  const [claimLoading, setClaimLoading] = useState(false)
  const [isOpenModal, setIsOpenModal] = useState(false)
  const [yieldList, setYieldList] = useState<any>([])
  const { getTokenAmountValue } = useTokenPrice()
  const { coinPriceObj } = useTokenPriceStore()
  const {
    myPosYieldValue,
    setMyPosYieldValue,
    posFeeDataLoading,
    posRewardsDataLoading,
    farmsPosRewardsDataLoading,
    posBaseList,
    posLiquidityData,
    posBaseListLoading,
    posLiquidityDataLoading,
    posFeeData,
    posRewardsData,
    farmsPosRewardsData
  } = usePositionStore()

  const { dlmmPosBaseList, dlmmPosLiquidityData, dlmmPosBaseListLoading, dlmmPosRewardsDataLoading, dlmmPosRewardsData, dlmmPosFeeData } =
    useDlmmPositionStore()

  const { clmmTotalTvl, dlmmTotalTvl } = useGetProfileLiquidityTvl()

  const showClmmLoading = !currentAccount?.address ? false : posBaseListLoading
  const showDlmmLoading = !currentAccount?.address ? false : dlmmPosBaseListLoading
  const { calculatePendingYield } = useCalculatePendingYield()

  useEffect(() => {
    if (!currentAccount?.address) {
      setMyPosYieldValue('')
      setYieldList([])
    } else {
      if (!posBaseListLoading && posBaseList?.length <= 0 && !dlmmPosBaseListLoading && dlmmPosBaseList?.length <= 0) {
        setMyPosYieldValue('0')
        setYieldList([])
      }
      if (
        (posBaseList?.length > 0 || dlmmPosBaseList?.length > 0) &&
        currentAccount?.address &&
        !posBaseListLoading &&
        !posFeeDataLoading &&
        !posRewardsDataLoading &&
        !farmsPosRewardsDataLoading &&
        !dlmmPosBaseListLoading &&
        !dlmmPosRewardsDataLoading
      ) {
        console.log('🚀 ~ useEffect ~ posBaseList:', {
          posBaseList,
          dlmmPosBaseList,
          posFeeData,
          posRewardsData,
          farmsPosRewardsData,
          dlmmPosFeeData,
          dlmmPosRewardsData
        })
        const { total, rewardAndFeeList } = calculatePendingYield(
          posBaseList,
          posFeeData,
          posRewardsData,
          farmsPosRewardsData,
          dlmmPosBaseList,
          dlmmPosFeeData,
          dlmmPosRewardsData
        )
        setMyPosYieldValue(total)
        setYieldList(rewardAndFeeList)
      }
    }
  }, [
    posBaseList,
    posBaseListLoading,
    posFeeDataLoading,
    posRewardsDataLoading,
    farmsPosRewardsDataLoading,
    dlmmPosBaseListLoading,
    dlmmPosRewardsDataLoading,
    currentAccount,
    coinPriceObj
  ])

  console.log('🚀 ~ myPosYieldValue:', myPosYieldValue)

  const showYieldLoading = !currentAccount?.address ? false : !myPosYieldValue
  const { isApp } = useWindowWidth()

  const claimDisabled = useMemo(() => {
    return Number(myPosYieldValue) <= 0 || claimLoading
  }, [myPosYieldValue, claimLoading])
  return (
    <>
      {isProfile && isApp ? (
        <Block borderRadius="12px">
          <HStack w="100%" gap="12px" justify="space-between">
            <VStack w="50%" align="flex-start">
              <Text>CLMM</Text>
              <Skeleton isLoaded={!!clmmTotalTvl}>
                <HiddenDotted size="l">
                  <TotalTvl totalTvl={clmmTotalTvl} isProfile />
                </HiddenDotted>
              </Skeleton>
            </VStack>
            <VStack w="50%" align="flex-start">
              <Text>DLMM</Text>
              <Skeleton isLoaded={!!dlmmTotalTvl}>
                <HiddenDotted size="l">
                  <TotalTvl totalTvl={dlmmTotalTvl} isProfile />
                </HiddenDotted>
              </Skeleton>
            </VStack>
            <Box h="44px" w="1px" bg="border" />
            <VStack w="50%" align="flex-start">
              <HStack w="100%" justify="space-between">
                <Text> Pending Yield</Text>
                <Text fontSize="12px" color={!claimDisabled ? 'primary' : ''} onClick={claimDisabled ? () => {} : () => setIsOpenModal(true)}>
                  Claim All
                </Text>
              </HStack>
              <Skeleton isLoaded={!showYieldLoading}>
                <HiddenDotted size="l">
                  <PendingYieldValue yieldList={yieldList} isProfile />
                </HiddenDotted>
              </Skeleton>
            </VStack>
          </HStack>
        </Block>
      ) : (
        <Stack flexDir={{ base: 'column', lg: 'row' }} w="100%" gap="16px">
          <HStack
            justify="flex-start"
            gap="100px"
            w={{ base: '100%', lg: '50%' }}
            p="0 20px"
            h="80px"
            borderRadius="14px"
            bgColor="card_bg"
            bgImage={tvl_bg}
            backgroundSize="100% 100%"
          >
            <HStack gap="12px">
              <VStack align="flex-start">
                <Text fontSize="14px" color="primary_gray">
                  CLMM
                </Text>
                <Skeleton isLoaded={!!clmmTotalTvl}>
                  <HiddenDotted size="l">
                    <TotalTvl totalTvl={clmmTotalTvl} />
                  </HiddenDotted>
                </Skeleton>
              </VStack>
            </HStack>
            <HStack gap="12px">
              <VStack align="flex-start">
                <Text fontSize="14px" color="primary_gray">
                  DLMM
                </Text>
                <Skeleton isLoaded={!!dlmmTotalTvl}>
                  <HiddenDotted size="l">
                    <TotalTvl totalTvl={dlmmTotalTvl} />
                  </HiddenDotted>
                </Skeleton>
              </VStack>
            </HStack>
          </HStack>

          <HStack
            justifyContent="space-between"
            p="0 20px"
            w={{ base: '100%', lg: '50%' }}
            h="80px"
            borderRadius="14px"
            bgColor="card_bg"
            bgImage={yield_bg}
            backgroundSize="100% 100%"
          >
            <Text fontSize="16px" color="primary_gray">
              Pending Yield
            </Text>
            <Skeleton isLoaded={!showYieldLoading}>
              {/* {isApp ? (
                <HStack gap="20px">
                  <VStack align="flex-end">
                    <PendingYieldValue yieldList={yieldList} />
                    <Button
                      isLoading={claimLoading}
                      isDisabled={claimDisabled}
                      w="100px"
                      h="24px"
                      onClick={() => setIsOpenModal(true)}
                      borderRadius="8px"
                      fontSize="12px"
                      fontWeight="500"
                    >
                      Claim All
                    </Button>
                  </VStack>

                  {Number(myPosYieldValue) > 0 && <Icon xlinkHref="#icon-icon_spread" onClick={() => setIsOpenModal(true)} />}
                </HStack>
              ) : ( */}
              <HStack onClick={() => setIsOpenModal(true)}>
                <HiddenDotted size="l">
                  <PendingYieldValue yieldList={yieldList} />
                </HiddenDotted>
                {Number(myPosYieldValue) > 0 && <Icon xlinkHref="#icon-icon_spread" />}
                <Button
                  isLoading={claimLoading}
                  isDisabled={claimDisabled}
                  w={{ base: 'unset', lg: '112px' }}
                  p={{ base: '8px', lg: 'unset' }}
                  h={{ base: '28px', lg: '32px' }}
                  borderRadius="8px"
                  fontSize={{ base: '12px', lg: '14px' }}
                  fontWeight="500"
                >
                  Claim All
                </Button>
              </HStack>
              {/* )} */}
            </Skeleton>
          </HStack>
          <PendingYieldModal
            showLoading={showClmmLoading || showDlmmLoading}
            isOpen={isOpenModal}
            claimLoading={claimLoading}
            onClose={() => setIsOpenModal(false)}
            changeClaimLoading={(status: boolean) => setClaimLoading(status)}
          />
        </Stack>
      )}
    </>
  )
}

const TotalTvl = ({ totalTvl, isProfile = false }: { totalTvl: string | number; isProfile?: boolean }) => {
  return (
    <Text fontSize={{ base: isProfile ? '16px' : '20px', lg: '20px' }} color="text_caption" fontStyle="500">
      {'$' + totalTvl == '--' ? '--' : formatCurrency(totalTvl, 2)}
    </Text>
  )
}

export const LiquidityAndYieldBg = ({ leftChildren, rightChildren }: { leftChildren: React.ReactNode; rightChildren: React.ReactNode }) => {
  return (
    <Stack flexDir={{ base: 'column', lg: 'row' }} w="100%" gap={{ base: '12px', lg: '20px' }}>
      <HStack
        w={{ base: '100%', lg: '50%' }}
        p={{ base: '0 12px ', lg: '0 20px' }}
        h={{ base: '60px', lg: '80px' }}
        borderRadius="14px"
        bgColor="card_bg"
        bgImage={tvl_bg}
        backgroundSize="100% 100%"
      >
        {leftChildren}
      </HStack>
      <HStack
        p={{ base: '0 12px ', lg: '0 20px' }}
        w={{ base: '100%', lg: '50%' }}
        h={{ base: '60px', lg: '80px' }}
        borderRadius="14px"
        bgColor="card_bg"
        bgImage={yield_bg}
        backgroundSize="100% 100%"
      >
        {rightChildren}
      </HStack>
    </Stack>
  )
}

export default LiquidityAndYield
